class Problem {
    /**
     * Given a list of logs representing folder operations,
     * return the minimum number of steps required to return to the main folder.
     *
     * Example:
     * Input: logs = ["d1/","d2/","../","d21/","./"]
     * Output: 2
     * Explanation: Perform the "../" operation twice to return to the main folder.
     *
     * Input: logs = ["d1/","d2/","./","d3/","../","d31/"]
     * Output: 3
     *
     * Input: logs = ["d1/","../","../","../"]
     * Output: 0
     */
  public int minOperations(String[] logs)  {
      // Initialize a counter for the current depth in the folder structure
      int depth = 0;

      // Iterate through each log entry
      for (String log : logs) {
          if (log.equals("../")) {
              // If the log is "../", move up one level if not already at the root
              if (depth > 0) {
                  depth--;
              }
          } else if (!log.equals("./")) {
              // If the log is not "./", move down one level
              depth++;
          }
      }

      // Return the final depth, which represents the minimum number of steps back to the main folder
      return depth;
  }
  public static void main(String[] args) {
    Problem solution = new Problem();

    // Test the function with different test cases
    assert solution.minOperations(
      new String[] { "d1/", "d2/", "../", "d21/", "./", "../" }
    ) ==
    1;
    assert solution.minOperations(
      new String[] { "d1/", "d2/", "./", "d3/", "../", "d31/", "../" }
    ) ==
    2;
    assert solution.minOperations(
      new String[] { "d1/", "../", "../", "../", "d2/" }
    ) ==
    1;
    System.out.println("All tests passed");
  }
}
